typedef struct {
    int online;
    void (*notify)(void *user, int online);
    void *user;
} online_status_t;

void online_status_init(online_status_t *s, void (*cb)(void *, int), void *user);
void online_status_set(online_status_t *s, int online);   /* calls s->notify */
void online_status_destroy(online_status_t *s);           /* unregister listeners */
